import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1166, own='cte_89.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 695 Practicum in IT: IT Support ----
H("695.d.1.A",3,"A help desk technician stays calm, listens fully and fixes a caller's printer issue the same day. These habits show:","excellent customer service",["poor time management","a hardware failure","a security breach"],"Patience, listening and follow-through define good service.")
H("695.d.1.A",4,"Which behavior best models excellent customer service when a caller is frustrated?","Acknowledging the frustration and focusing on a solution",["Telling the caller to calm down","Reading a script without listening","Transferring the call immediately"],"Empathy plus action builds trust.")
H("695.d.1.B",3,"When answering a support line, the best way to open a contact is to:","greet the caller, give your name and offer help",["ask for payment first","wait silently","ask what they did wrong"],"A friendly opening sets the tone.")
H("695.d.1.B",4,"After greeting a caller and giving your name, the next step in opening a contact is to:","ask how you can help and gather the issue details",["close the ticket","transfer to a manager","email a survey"],"Open with a greeting, then identify the need.")
H("695.d.1.C",3,"Using a client's name during a support call helps to:","build rapport and make the client feel valued",["speed up the modem","lower the call volume","avoid documentation"],"Names personalize the service.")
H("695.d.1.C",4,"A technician overuses a client's name in every sentence. This habit can:","sound insincere and annoy the client",["improve the connection","fix the problem faster","protect the client's data"],"Moderation keeps the tone natural.")
H("695.d.1.D",3,"Which habit should a technician avoid when talking with a client?","Using technical jargon the client doesn't understand",["Speaking clearly","Summarizing the issue","Thanking the client"],"Jargon confuses non-technical users.")
H("695.d.1.D",4,"A technician interrupts a client who is explaining a problem. This habit is harmful because it:","can cause missed details and damage trust",["shortens every call","improves accuracy","lowers costs"],"Interrupting hides key information.")
H("695.d.1.E",3,"A repair will take two extra days because a part is backordered. The technician should:","tell the client about the delay promptly",["wait until the client asks","close the ticket","hope they don't notice"],"Clients should be kept informed.")
H("695.d.1.E",4,"Keeping clients informed of status changes mainly helps to:","manage expectations and reduce repeat calls",["increase part costs","hide mistakes","avoid documentation"],"Updates prevent frustration and follow-ups.")
H("695.d.1.F",3,"Before placing a caller on hold, a technician should:","ask permission and explain why",["hang up","mute the call silently","say nothing"],"Courtesy before hold avoids frustration.")
H("695.d.1.F",4,"When transferring a call to another department, a good practice is to:","explain the transfer and give the next person the details",["transfer without telling the caller","let the caller repeat everything","drop the call"],"Warm transfers save time.")
H("695.d.1.G",3,"A caller is shouting about a lost file. The best first response is to:","listen, stay calm and acknowledge the concern",["shout back","hang up","argue about the cause"],"De-escalation starts with calm listening.")
H("695.d.1.G",4,"When a difficult caller demands a solution outside policy, a technician should:","explain what can be done and offer an alternative or escalation",["promise the impossible","ignore the request","end the call"],"Stay honest and solution-oriented.")
H("695.d.1.H",3,"After a support call, the technician writes down the issue, steps taken and the result. This is:","documenting the communication and outcome",["wasting time","deleting evidence","optional busywork"],"Records support follow-up.")
H("695.d.1.H",4,"A well-written ticket note should be:","clear, accurate and professional",["vague and short","full of slang","left blank"],"Good notes help the next technician.")
H("695.d.2.A",3,"Which skill is most important for an IT support specialist when explaining a fix to a non-technical user?","clear communication",["soldering","video editing","web design"],"Explaining well is core to support.")
H("695.d.2.A",4,"An IT support specialist's primary responsibilities include troubleshooting issues, documenting fixes and:","providing user assistance and escalating when needed",["designing company logos","managing payroll","selling hardware"],"Support covers help, documentation and escalation.")
H("695.d.2.B",3,"Before opening a new computer box, a technician should check for:","visible shipping damage and verify the contents",["music","the weather","a login"],"Inspection prevents later disputes.")
H("695.d.2.B",4,"Handling a hard drive safely during repacking means using:","anti-static protection and cushioned packaging",["loose newspaper only","a plastic bag with no padding","rubber bands"],"Static and shock can damage components.")
H("695.d.2.C",3,"Remote support tools let a technician fix a problem without:","traveling to the user's location",["the user's permission","an internet connection","any software"],"Remote tools save travel time.")
H("695.d.2.C",4,"A client needs a hardware part swapped in a locked server room. The best support method is:","in-person support",["an instant message","a voice mail","a text survey"],"Hands-on work requires being there.")
H("695.d.2.D",3,"A user emails a question and gets a written reply with steps. This is which support delivery model?","email support",["remote desktop control","on-site repair","a walk-up desk"],"Written replies are email support.")
H("695.d.2.D",4,"Support delivered by phone while the technician talks the user through steps is:","telephone support",["in-person support","automated support","self-service articles"],"Voice guidance is phone support.")
H("695.d.2.E",3,"The security management process in IT support aims to:","protect information and systems from threats",["raise hardware prices","increase user passwords' length only","remove user accounts"],"Security management protects assets.")
H("695.d.2.E",4,"An IT support specialist supports the security process by:","following policies and reporting suspicious activity",["sharing admin passwords","disabling updates","ignoring alerts"],"Support staff are a first line of defense.")
H("695.d.3.A",3,"A technician asks questions, tests one change at a time and verifies the fix. This is:","a troubleshooting process",["random guessing","a hardware upgrade","a software license"],"Structured steps find causes.")
H("695.d.3.A",4,"After a solution restores a printer, the next step in a troubleshooting process is to:","verify the fix and document the findings",["restart from the beginning","delete the printer","blame the user"],"Verification and documentation close the loop.")
H("695.d.3.B",3,"Writing down each troubleshooting step helps because:","it prevents repeating steps and aids later technicians",["it slows the repair","it hides the cause","it is never useful"],"Notes capture what has been tried.")
H("695.d.3.B",4,"A ticket has no notes and the issue returns. The next technician will likely:","repeat tests that were already done",["fix it instantly","skip troubleshooting","know the exact cause"],"Missing notes waste time.")
H("695.d.3.C",3,"A help desk service level model sets expectations for:","response and resolution times",["office decor","employee birthdays","parking spots"],"SLAs define time targets.")
H("695.d.3.C",4,"Incident management activities include logging an issue, categorizing it and:","resolving it and closing the ticket",["buying new offices","firing the user","changing the logo"],"The incident lifecycle ends in resolution.")
H("695.d.3.D",3,"A server outage affecting everyone is best described as an:","incident",["upgrade","training","warranty"],"Incidents disrupt service.")
H("695.d.3.D",4,"The same printer jams every week for the same underlying reason. This repeating cause is called a:","problem",["greeting","training event","new hire"],"Problems are root causes of repeated incidents.")
H("695.d.3.E",3,"An operational level agreement (OLA) describes the commitments between:","internal teams that support a service",["a company and its customers only","two unrelated vendors","a user and their family"],"OLAs define internal responsibilities.")
H("695.d.3.E",4,"An IT support specialist uses an OLA to know:","how quickly another internal team must respond to a handoff",["what the user's salary is","which colors to use","who owns the building"],"OLAs set internal response targets.")
H("695.d.3.F",3,"A technician cannot fix a network outage with the tools available. The next step is to:","escalate to a higher-level team",["close the ticket","ignore it","delete logs"],"Escalation passes unresolved issues up.")
H("695.d.3.F",4,"A reason an incident may be escalated is that it:","is beyond the technician's authority or skill level",["was solved quickly","has no user","is a duplicate greeting"],"Escalate when you can't resolve it.")
H("695.d.3.G",3,"Applying a security patch to a company laptop is an example of:","a system update",["a data deletion","a hardware sale","a license theft"],"Updates close known vulnerabilities.")
H("695.d.3.G",4,"Before rolling out a major update to many devices, a technician should first:","test it on a small group of devices",["push it to everyone at once","skip the backup","turn off all computers"],"Pilot testing reduces risk.")
H("695.d.3.H",3,"A service level target for a help desk could be to:","answer 90% of calls within 60 seconds",["ignore calls","answer calls in a week","never record calls"],"Targets are measurable.")
H("695.d.3.H",4,"Service center metrics such as first-call resolution rate help managers to:","measure and improve support quality",["raise rent","buy more office plants","reduce staff breaks"],"Metrics guide improvement.")
H("695.d.4.A",3,"A student uses the school's computers only for approved class work, as the acceptable use policy states. This shows:","positive digital citizenship",["a policy violation","poor planning","a network fault"],"Following policy is responsible behavior.")
H("695.d.4.A",4,"Posting a kind, accurate comment on a class forum and reporting a rude one shows:","responsible digital citizenship",["spamming","identity theft","trolling"],"Respectful action builds a positive online community.")
H("695.d.4.B",3,"Which password change makes it hardest for attackers to guess?","Making it longer and adding unrelated words and symbols",["Using your birthday","Using the word 'password'","Using your pet's name only"],"Length and variety increase strength.")
H("695.d.4.B",4,"A good practice for protecting accounts is to:","use a different strong password for each account",["reuse one password everywhere","write it on a sticky note on the monitor","share it with coworkers"],"Unique passwords limit breach damage.")
H("695.d.4.C",3,"Before using a student's photo in a school newsletter, staff should follow guidelines on:","permission and privacy",["font choices","paper weight","printer speed"],"Media use requires consent.")
H("695.d.4.C",4,"A technician receives a request to post an employee's personal details online. The guidelines say to:","verify authorization and protect private information",["post it right away","email it to everyone","ignore all rules"],"Privacy guidelines limit disclosure.")
H("695.d.4.D",3,"A work published for anyone to use freely, with no copyright restrictions, is in the:","public domain",["private archive","trade secret","patent office"],"Public domain works are free to use.")
H("695.d.4.D",4,"A photographer lets others reuse her photo if they give credit. This is typical of a:","Creative Commons license",["trade secret","patent","trademark"],"Creative Commons allows reuse with conditions.")
H("695.d.4.E",3,"A company buys 10 software licenses but installs the program on 40 computers. This violates:","the software licensing terms",["a font rule","a color rule","a file naming rule"],"Licenses limit installations.")
H("695.d.4.E",4,"A technician finds an unlicensed copy of paid software on a workstation. The correct action is to:","report it and bring the license into compliance",["ignore it","copy it to more machines","hide it"],"Compliance protects the company.")
H("695.d.4.F",3,"Encryption protects data by:","scrambling it so only authorized users can read it",["deleting it","compressing it only","printing it"],"Encryption makes data unreadable without a key.")
H("695.d.4.F",4,"A lost laptop with an encrypted drive is less risky because:","the data cannot be read without the key",["the laptop can't be sold","the screen is locked forever","the battery is dead"],"Encryption protects data at rest.")
H("695.d.4.G",3,"A technician sees a customer's account number on a screen while repairing a computer. Best practice is to:","avoid copying or sharing it",["post it online","email it to coworkers","write it on a whiteboard"],"Confidential data stays confidential.")
H("695.d.4.G",4,"Confidential paper records that are no longer needed should be:","securely shredded",["thrown in the recycling bin whole","left on a desk","mailed to a friend"],"Proper destruction prevents leaks.")
H("695.d.4.H",3,"An email pretends to be from the IT department and asks for a user's password. This is an example of:","social engineering",["a software update","a hardware warranty","a backup"],"Attackers manipulate people to get information.")
H("695.d.4.H",4,"A good way to reduce the risk of social engineering is to:","verify unexpected requests through a known, trusted channel",["click all links quickly","share passwords on request","ignore training"],"Verification stops impersonation.")
H("695.d.4.I",3,"A policy that says visitors must sign in and wear badges is a:","physical security measure",["software patch","password reset","network protocol"],"Badges and logs control physical access.")
H("695.d.4.I",4,"Physical security matters in IT because someone with physical access to a server can often:","bypass software protections",["improve the network","repair the policy","delete the laws"],"Physical access can defeat digital controls.")
H("695.d.4.J",3,"A user notices strange pop-ups after opening an email attachment. They should:","report it to IT support right away",["ignore it","forward the attachment","turn off the monitor"],"Prompt reporting limits damage.")
H("695.d.4.J",4,"Reporting a security compromise promptly helps because it:","lets the organization contain and fix the problem sooner",["increases downtime","hides the cause","raises the budget"],"Speed limits harm.")
H("695.d.4.K",3,"Before donating an old computer, a technician should:","wipe or destroy the drive so data can't be recovered",["leave all files on it","delete only the desktop icons","write passwords inside the case"],"Proper sanitization protects data.")
H("695.d.4.K",4,"Which method most reliably prevents data recovery from a retired hard drive?","Physical destruction or certified wiping",["Emptying the recycle bin","Renaming the files","Moving files to another folder"],"Deleting files is not enough.")
H("695.d.5.A",3,"Before installing a CPU, a technician should:","power off, unplug and use anti-static protection",["leave the power on","touch the pins","wear wool gloves"],"ESD and power safety come first.")
H("695.d.5.A",4,"When installing a processor on a motherboard, the technician must line up:","the notch or triangle marker with the socket",["the heat sink with the case door","the label with the monitor","the cables with the fan"],"Alignment marks prevent bent pins.")
H("695.d.5.B",3,"A basic way to secure a workstation is to require:","a login password and a locked screen when away",["no login at all","a shared admin account for all","default passwords forever"],"Access control protects the workstation.")
H("695.d.5.B",4,"Securing a workstation also includes keeping the operating system and software:","up to date with security patches",["exactly as shipped","turned off","unlicensed"],"Patching closes vulnerabilities.")
H("695.d.5.C",3,"A computer shows no lights and no fan spin when the power button is pressed. This symptom is called:","no power",["a POST beep error","a blue screen","a slow network"],"No power suggests a supply or outlet problem.")
H("695.d.5.C",4,"A system powers on but fails before the operating system loads and gives beep codes. The problem is detected during:","POST (power-on self-test)",["a Windows update","a web search","a screen saver"],"POST checks hardware at startup.")
H("695.d.5.D",3,"A machine shows memory errors. A technician can troubleshoot by:","reseating or replacing the RAM modules",["reinstalling the printer","replacing the monitor cable","updating the web browser"],"RAM modules can loosen or fail.")
H("695.d.5.D",4,"When installing new RAM, the notch on the module must match:","the key in the slot",["the case color","the logo","the fan size"],"Keys ensure correct orientation.")
H("695.d.5.E",3,"A computer overheats and shuts down. A technician should first check and clean:","the fans and heat sink for dust",["the keyboard keys","the mouse ball","the speaker cone"],"Dust blocks airflow.")
H("695.d.5.E",4,"Thermal paste is applied between a CPU and its cooler to:","improve heat transfer",["glue the case shut","paint the board","lower the voltage"],"Paste fills microscopic gaps.")
H("695.d.5.F",3,"Cleaning fans and checking cables on a regular schedule is called:","periodic maintenance",["a data wipe","a license audit","a hardware recall"],"Routine upkeep prevents failure.")
H("695.d.5.F",4,"Software maintenance tasks include installing updates and:","running disk cleanup and scans",["removing the fan","replacing the case","painting the tower"],"Regular software upkeep keeps systems healthy.")
H("695.d.5.G",3,"A technician suspects malware. The first sensible step is usually to:","isolate the computer from the network",["share files with others","plug in more drives","delete the operating system"],"Isolation stops spread.")
H("695.d.5.G",4,"After removing malware with an approved tool, a technician should:","update the system and scan again to confirm it is clean",["assume it is clean","reinfect to test","share the infected file"],"Verification confirms removal.")
H("695.d.6.A",3,"A user cannot find a lost file. A built-in OS feature to try is:","the search tool",["a screwdriver","a toner cartridge","a router reset"],"OS search locates files.")
H("695.d.6.A",4,"A technician wants to see which programs slow a computer at startup. The OS tool to use is:","the task or startup manager",["a printer spooler","a spreadsheet","a web browser"],"Startup managers list launch items.")
H("695.d.6.B",3,"To check how much free space a drive has, a technician can use:","the disk management or storage utility",["a calculator","a word processor","an email client"],"Storage utilities show space.")
H("695.d.6.B",4,"A utility that rearranges data on a traditional hard disk so files are stored more efficiently is:","defragmentation",["encryption","compression of photos","a firewall"],"Defragmentation reduces seek time on HDDs.")
H("695.d.6.C",3,"On Windows, the command used to show a computer's network configuration is:","ipconfig",["format","notepad","diskpart only"],"ipconfig lists IP settings.")
H("695.d.6.C",4,"To see active network connections and listening ports, a technician types:","netstat",["dir","ping only","cls"],"netstat shows connections.")
H("695.d.6.D",3,"A computer frequently shows a blue error screen after a driver update. A sensible first step is to:","roll back or update the driver",["replace the monitor","buy a new keyboard","reinstall the printer paper"],"Drivers cause many OS crashes.")
H("695.d.6.D",4,"After solving an OS problem, a technician records the symptoms, steps taken and the:","final resolution",["weather","coffee order","stock price"],"Documentation helps future fixes.")
H("695.d.6.E",3,"A technician working on macOS should expect to find system settings in:","System Settings (or System Preferences)",["Control Panel only","a DOS prompt only","the BIOS only"],"Each OS has its own tools.")
H("695.d.6.E",4,"A Linux user can run commands and manage files using the:","terminal",["start orb","charms bar","dock bell"],"The terminal is Linux's command interface.")
H("695.d.6.F",3,"A Windows laptop won't boot but a Mac and a Linux laptop work fine. A technician should troubleshoot:","the Windows laptop's own OS and hardware",["the Mac's fan","the Linux partition","the network cable of the Mac"],"Troubleshoot the affected system.")
H("695.d.6.F",4,"When documenting problems across several operating systems, a technician should note the:","OS name, version and symptoms",["favorite color","lunch order","break times"],"Details help reproduce issues.")
H("695.d.6.G",3,"A database is used to:","store, organize and retrieve data",["print posters","cool servers","connect keyboards"],"Databases manage data.")
H("695.d.6.G",4,"In a database table, a single row of data about one customer is called a:","record",["field type","cable","protocol"],"Rows are records.")
H("695.d.7.A",3,"A new solid-state drive is installed in a laptop but the OS does not see it. The technician should first check that:","the drive is detected in BIOS/UEFI and initialized",["the keyboard is clean","the printer has paper","the monitor is bright"],"Detect, then initialize and format.")
H("695.d.7.A",4,"A drive that makes clicking noises and is slow is most likely showing signs of:","mechanical failure",["a loose mouse","a printer jam","a network outage"],"Clicking indicates failing moving parts.")
H("695.d.7.B",3,"A laser printer produces pages with black streaks. A common cause to check is:","a dirty or damaged drum or toner cartridge",["a loose monitor","a bad mouse","a slow modem"],"Streaks often come from toner or drum issues.")
H("695.d.7.B",4,"A multifunction office device can usually print, copy, scan and:","fax",["compile code","edit video","store passwords"],"MFDs combine several functions.")
H("695.d.7.C",3,"A projector shows a dim, yellowed image. The most likely maintenance item to check is the:","lamp (bulb) life and filters",["keyboard","mouse","printer"],"Aging lamps dim and shift color.")
H("695.d.7.C",4,"A monitor displays 'no signal' after a computer is turned on. A first check is the:","video cable connection and input source",["hard drive speed","printer driver","email settings"],"Cable and input selection cause most no-signal cases.")
H("695.d.7.D",3,"A conference attendee cannot be heard on a video call. A technician should first check the:","microphone connection, mute status and input selection",["monitor brightness","printer queue","keyboard layout"],"Mute and input settings are common culprits.")
H("695.d.7.D",4,"A webcam works in one app but not another. A likely cause is:","the second app lacks permission or is using the wrong camera",["a broken keyboard","a dead power supply","a full printer queue"],"Per-app permissions and device selection matter.")
H("695.d.8.A",3,"Laptop hardware differs from desktop hardware because laptop parts are often:","smaller and integrated into a compact case",["bigger and always removable","not repairable by anyone","free of any battery"],"Laptops use compact, tightly integrated components.")
H("695.d.8.A",4,"Before replacing a laptop's internal RAM, a technician should:","power off, disconnect the battery and AC adapter, and ground themselves",["leave the laptop on","skip static protection","remove the screen"],"Safety first protects the technician and parts.")
H("695.d.8.B",3,"A laptop screen is cracked. Replacing it requires carefully removing the:","bezel and the display panel connector",["power cord only","the printer","the keyboard only"],"Access to the display is through the bezel.")
H("695.d.8.B",4,"A technician replacing an internal display panel should handle the video ribbon cable:","gently to avoid tearing or bending it",["by pulling hard","with wet hands","by cutting it"],"Ribbon cables are fragile.")
H("695.d.8.C",3,"A user wants to connect an external monitor to a laptop. The technician should look for a:","video output port such as HDMI or USB-C",["card slot for a printer","speaker jack only","power button"],"Video ports connect displays.")
H("695.d.8.C",4,"A docking station helps a laptop user by providing:","multiple ports and charging through one connection",["more battery life by itself","a larger processor","a faster keyboard"],"Docks consolidate connections.")
H("695.d.8.D",3,"A basic way to secure a mobile phone is to enable:","a screen lock with a PIN or biometric",["no lock","auto-share of all data","an open Wi-Fi hotspot"],"Screen locks block unauthorized access.")
H("695.d.8.D",4,"If a company phone is lost, which feature can protect its data?","remote wipe",["screen brightness","auto-rotate","wallpaper change"],"Remote wipe erases data on a lost device.")
H("695.d.8.E",3,"A phone connects to Wi-Fi but cannot load web pages. A technician should check:","the network settings and credentials",["the camera lens","the speaker volume","the case color"],"Connectivity issues point to network settings.")
H("695.d.8.E",4,"Company email on a phone requires a:","configured account with the correct server settings",["screen protector","printer cable","game controller"],"App support needs correct account configuration.")
H("695.d.8.F",3,"Syncing a phone's contacts to a cloud account helps to:","keep the same contacts on all devices",["delete all contacts","slow the phone","remove the account"],"Sync keeps data consistent.")
H("695.d.8.F",4,"A user's calendar on a phone isn't matching their laptop. A technician should check:","that sync is enabled and the accounts match",["the keyboard backlight","the phone case","the volume level"],"Sync settings control updates.")
H("695.d.8.G",3,"A phone runs very slowly and apps crash. A reasonable first step is to:","restart the device and free up storage",["throw it away","buy a new case","paint it"],"Restarts and storage cleanup solve many issues.")
H("695.d.8.G",4,"An app crashes right after a mobile OS update. A technician should check for:","an app update compatible with the new OS",["a new screen protector","a wired network","a laptop battery"],"Compatibility updates fix post-update crashes.")
H("695.d.9.A",3,"A technician is running a new wired network in an office. The cable most commonly used for Ethernet is:","twisted-pair (Cat 6)",["coaxial for TV","speaker wire","extension cord"],"Ethernet uses twisted-pair cabling.")
H("695.d.9.A",4,"To secure a wired network, a technician can disable unused switch ports and:","use access controls on connected devices",["leave all ports open","label every port 'public'","share the admin password"],"Port security limits unauthorized connections.")
H("695.d.9.B",3,"The first step to secure a new wireless router is to:","change the default admin password and enable encryption",["leave default settings","broadcast the password","turn off the firewall"],"Defaults are well known to attackers.")
H("695.d.9.B",4,"Setting a wireless network to hide its SSID by itself is:","a weak security measure that is easy to bypass",["unbreakable","required by law","the strongest protection"],"Hidden SSIDs are still discoverable.")
H("695.d.9.C",3,"Which wireless security protocol is generally the most secure?","WPA3",["WEP","open (no security)","WPS only"],"WPA3 is the newest and strongest.")
H("695.d.9.C",4,"Which security setting is outdated and easily cracked?","WEP",["WPA3","WPA2","WPA2-Enterprise"],"WEP is obsolete.")
H("695.d.9.D",3,"One computer on the network can't reach the internet while others can. A technician should first check:","that computer's cable or Wi-Fi connection and IP settings",["the printer toner","the office lights","everyone's passwords"],"Isolate to the affected device.")
H("695.d.9.D",4,"If no devices on a Wi-Fi network can reach the internet, a likely cause is:","a problem with the router or modem",["a single laptop's battery","a keyboard","a user's phone case"],"Network-wide issues point to shared equipment.")
H("695.d.9.E",3,"A technician suspects a patch cable has a broken wire inside. A cable tester is used to:","check a network cable for breaks or wiring faults",["print documents","measure room temperature","clean the screen"],"Testers verify cable integrity.")
H("695.d.9.E",4,"To see whether a device can reach another over a network, a technician can use the:","ping command",["dir command","cls command","copy command"],"Ping tests reachability.")
H("695.d.9.F",3,"A phone and a laptop share a file over a home Wi-Fi network. They are communicating through the:","network and a wireless router",["USB mouse","printer driver","power cord"],"Devices connect through the network.")
H("695.d.9.F",4,"Two phones share a photo without a router by using a short-range wireless technology such as:","Bluetooth",["a coaxial line","fiber backbone","serial cable"],"Bluetooth supports direct device connections.")
H("695.d.9.G",3,"Cloud computing lets a company use servers and storage:","over the internet instead of owning them",["only on its own premises","without a network","without any software"],"Cloud resources are delivered online.")
H("695.d.9.G",4,"A feature of many cloud platforms that lets customers add or remove resources as needed is:","scalability",["fragility","immobility","isolation"],"Scalability fits changing demand.")
H("695.d.9.H",3,"A user cannot open a file stored in a cloud service. A technician should first check:","the user's sign-in, permissions and internet connection",["the printer toner","the keyboard keys","the monitor stand"],"Access and connectivity are common causes.")
H("695.d.9.H",4,"A cloud virtual machine is running slowly. A technician may review its resource use and:","increase its memory or CPU allocation",["unplug the keyboard","replace the monitor","clean the mouse"],"Resizing resources can fix performance.")

# ---- 696 ----
H("696.d.1.A",3,"A team lists who will use a robot arm, what it must lift and where it will work. They are:","identifying the elements of an engineering problem",["testing a finished product","selling the product","recycling the parts"],"Defining users, tasks and setting frames the problem.")
H("696.d.1.A",4,"Which question best helps an engineer analyze a problem before designing a fix?","What need must the solution meet, and for whom?",["Which color looks best?","Who can build it fastest?","What did it cost last year?"],"Needs and users drive the design.")
H("696.d.1.B",3,"A programmer breaks a game idea into inputs, rules, scoring and outputs. This step is:","analyzing the structure of a programming problem",["debugging syntax errors","publishing the app","compressing images"],"Decomposition reveals a problem's structure.")
H("696.d.1.B",4,"Splitting a large program task into smaller sub-problems helps because each piece is:","easier to understand, build and test",["impossible to test","hidden from the user","guaranteed bug-free"],"Smaller parts are manageable.")
H("696.d.1.C",3,"A client says the timer app must work offline. This statement is:","pertinent customer information about a requirement",["a bug report","a code comment","a legal notice"],"Customer statements reveal requirements.")
H("696.d.1.C",4,"Before changing an existing program for a customer, a developer should first:","read what it already does and ask what the customer needs changed",["rewrite it from scratch immediately","delete the old code","skip the customer meeting"],"Understand the current program and the need.")
H("696.d.1.D",3,"A team weighs two ways to store scores: a file or a database. They are:","comparing alternatives to a solution",["debugging a loop","naming variables","drawing a logo"],"Alternatives are compared before choosing.")
H("696.d.1.D",4,"Critical thinking when choosing between designs means judging each option by:","evidence and how well it meets requirements",["which one is newest","which one a friend likes","which one is shortest"],"Decisions rest on evidence and criteria.")
H("696.d.1.E",3,"Before choosing a sensor for a robot, a student reads its datasheet. This is:","researching technical information for a decision",["testing a prototype","a final report","peer grading"],"Datasheets give specs for choosing parts.")
H("696.d.1.E",4,"Which source is most reliable for a microcontroller's voltage limits?","The manufacturer's datasheet",["A random forum guess","A friend's memory","A product photo"],"Primary documentation is most reliable.")
H("696.d.2.A",3,"Before using a hot-glue gun in the lab, a student should:","wear eye protection and keep fingers away from the nozzle",["remove all safety gear","leave it plugged in unattended","cut toward their hands"],"Basic lab safety prevents burns and cuts.")
H("696.d.2.A",4,"When cutting material with a hobby knife, the safe method is to:","cut away from the body on a cutting mat",["cut toward your hand","hold the material in your lap","cut without a mat"],"Cutting away from the body avoids injury.")
H("696.d.2.B",3,"Loose batteries and wires should be stored:","in labeled containers so terminals cannot short",["loose in a pocket","touching metal tools","in direct sunlight on a bench"],"Preventing shorts prevents fires.")
H("696.d.2.B",4,"Before changing wiring on a powered breadboard circuit, a student should:","disconnect the power first",["leave it powered","touch both rails","add more voltage"],"Unpower circuits before changing them.")
H("696.d.2.C",3,"Leftover wire scraps and dead batteries should be:","recycled or disposed of in the proper bins",["thrown on the floor","mixed with food waste","hidden in a drawer"],"Electronics need proper disposal.")
H("696.d.2.C",4,"Reusing a breadboard and jumper wires for a new project is an example of:","conserving resources by reusing materials",["wasting resources","ignoring safety","avoiding testing"],"Reuse reduces waste.")
H("696.d.3.A",3,"A project must cost under $50 and be done in two weeks. These limits are:","constraints",["bugs","comments","variables"],"Constraints are limits on a design.")
H("696.d.3.A",4,"A constraint evaluation asks whether a design:","stays within limits such as cost, time and size",["is the prettiest","uses the most parts","is the most complex"],"Designs must fit their constraints.")
H("696.d.3.B",3,"Adding a guard around spinning motor blades protects the:","user",["compiler","spreadsheet","password"],"Guards are user safety features.")
H("696.d.3.B",4,"Safety in a design should consider the system, the engineer building it and the:","user operating it",["competition's logo","paper supplier","weather forecast"],"Safety covers system, engineer and user.")
H("696.d.3.C",3,"Copying someone's code into a project without permission or credit raises an issue of:","intellectual property and attribution",["better efficiency","faster loading","color theory"],"Using others' work requires permission and credit.")
H("696.d.3.C",4,"A student uses open-source code whose license requires crediting the author. They must:","include the required attribution",["claim it as their own","remove the license","sell it secretly"],"Open-source licenses have conditions.")
H("696.d.4.A",3,"A customer says, \"The app should be easy for my grandmother to use.\" The need is:","simplicity and ease of use",["higher cost","more colors","faster servers"],"Customer words reveal needs.")
H("696.d.4.A",4,"Turning a customer's vague wish into a specific need is done by:","asking clarifying questions and analyzing their answers",["guessing quietly","ignoring the comment","building first"],"Analysis makes needs concrete.")
H("696.d.4.B",3,"A diagram showing steps a user takes to log in and what the system does is a:","process flow diagram",["Pugh chart","bar graph","periodic table"],"Process flow diagrams map actions.")
H("696.d.4.B",4,"A process flow diagram can reveal design opportunities by showing:","where users get stuck or steps can be simplified",["the paper color","the programmer's name","the keyboard type"],"It highlights friction points.")
H("696.d.4.C",3,"A flowchart uses a diamond shape for a:","decision",["start point","process step","data store"],"Diamonds mean yes/no decisions.")
H("696.d.4.C",4,"A flowchart for a program should be developed from:","the results of the process flow diagram",["random sketches","finished code only","the final report"],"Flowcharts translate process flows to program logic.")
H("696.d.4.D",3,"A target specifications table lists:","measurable goals for the product",["the team's lunch plans","the grading rubric","random facts"],"Target specs are measurable.")
H("696.d.4.D",4,"Which entry belongs in a target specifications table?","Response time under 2 seconds",["Looks nice","Pretty good","Fun to use"],"Specs must be measurable.")
H("696.d.4.E",3,"A team studies two existing timer apps before building their own. They are:","identifying similar existing solutions",["debugging","encrypting data","deleting files"],"Benchmarking learns from existing products.")
H("696.d.4.E",4,"Describing the strengths and weaknesses of existing solutions helps a team to:","find gaps their design can improve on",["copy it exactly","avoid all research","ignore the customer"],"Gaps become design opportunities.")
H("696.d.4.F",3,"A functional model shows the:","functions a product performs and how they connect",["paint colors","team schedule","parts' prices"],"Functional models map functions.")
H("696.d.4.F",4,"Building a functional model from customer needs helps generate ideas for:","user actions and product functions",["lunch menus","office layouts","tax forms"],"Models inspire designs.")
H("696.d.5.A",3,"For a quiz app, the essential user tasks are likely to include:","starting the quiz, answering questions and viewing the score",["changing the compiler","editing the source code","wiring the router"],"Essential tasks are what users must do.")
H("696.d.5.A",4,"Identifying essential tasks first lets designers:","focus the interface on what users must accomplish",["add random features","remove all buttons","hide the program"],"Task focus drives design.")
H("696.d.5.B",3,"A user types letters into a field meant for a number. The program should handle this:","unexpected input",["power failure","hardware wear","color blindness"],"Programs must handle bad input.")
H("696.d.5.B",4,"A developer predicts that new users might click 'Submit' with an empty form. This is identifying:","a point of potential confusion",["a finished feature","a licensing term","a battery issue"],"Anticipating confusion improves design.")
H("696.d.5.C",3,"A clear interface uses labeled buttons that:","tell the user what each button does",["are all the same color without labels","hide their purpose","change names randomly"],"Clarity guides users.")
H("696.d.5.C",4,"A well-designed interface reduces errors by:","guiding the user with clear prompts and feedback",["removing all text","using tiny fonts","adding secret menus"],"Prompts and feedback prevent mistakes.")
H("696.d.5.D",3,"Supplemental instructions such as a README or FAQ explain things like:","how to start the program",["how to buy a computer","how to paint the case","how to rewrite the OS"],"Supplements cover what the interface can't.")
H("696.d.5.D",4,"A frequently asked questions page helps users by:","answering common questions in one place",["hiding the program","replacing the interface","deleting errors"],"FAQs reduce confusion.")
H("696.d.5.E",3,"Testing a program with someone who has never seen it helps find:","confusing steps the creator no longer notices",["syntax colors","compiler flags","fan noise"],"Fresh eyes expose blind spots.")
H("696.d.5.E",4,"During a new-user test, the developer should mostly:","observe quietly and take notes",["explain every step","do the task for the user","argue with the tester"],"Observing shows real behavior.")
H("696.d.5.F",3,"After new-user testing, five of six testers couldn't find the Save button. This result suggests:","the button needs to be easier to find",["the testers are careless","the code is perfect","the manual is too long"],"Common failures point to design problems.")
H("696.d.5.F",4,"When evaluating feedback, a developer should prioritize:","problems that several users hit",["a single unusual opinion","the loudest comment only","the cheapest fix only"],"Repeated issues matter most.")
H("696.d.5.G",3,"A team moves the Save button and adds a label after testing. This is:","refining the program based on feedback",["ignoring results","starting over","cancelling the project"],"Iteration improves designs.")
H("696.d.5.G",4,"After revising a program, the instructions should also be:","updated to match the changes",["left unchanged","deleted","hidden"],"Documentation must match the product.")
H("696.d.5.H",3,"After making changes from user feedback, the team should:","re-test the program with users",["ship without testing","delete the feedback","stop the project"],"Retesting confirms the fixes work.")
H("696.d.5.H",4,"At the end of a re-test, the team identifies next steps such as:","remaining issues to fix and features to add",["destroying the code","hiding the results","changing teams"],"Next steps carry the project forward.")
H("696.d.6.A",3,"A tester enters a letter where a number is expected to see if the program crashes. This is:","break testing",["code compression","licensing","flowcharting"],"Break testing tries to make the program fail.")
H("696.d.6.A",4,"Writing tests for an existing program mainly determines whether it:","works as intended under many inputs",["has pretty colors","uses short names","is open source"],"Tests confirm functionality.")
H("696.d.6.B",3,"While reading old code, a student finds a function that does something not mentioned in its comments. This is:","an unexpected finding",["a planned feature","a licensing step","a flowchart symbol"],"Deconstruction can reveal surprises.")
H("696.d.6.B",4,"When deconstructing code gives unexpected results, the best response is to:","describe what was found and investigate why",["ignore it","delete the code","assume it is fine"],"Unexpected behavior needs explanation.")
H("696.d.6.C",3,"Before using a software library, a developer should read its documentation to learn its:","uses and functionality",["price tag","logo","author's hobbies"],"Docs explain what a library can do.")
H("696.d.6.C",4,"A programmer imports a library for math functions instead of writing them. This choice mainly:","saves time by reusing tested code",["makes the code unreadable","removes the need for testing","hides bugs forever"],"Libraries provide reusable functionality.")
H("696.d.6.D",3,"Constructing a flowchart for an existing program shows:","the program's logic and flow",["the programmer's age","the monitor size","the mouse type"],"Flowcharts visualize program flow.")
H("696.d.6.D",4,"To build a flowchart from existing code, a student traces the code and draws:","each step and decision in order",["only the last line","random shapes","the file names only"],"Trace the logic in order.")
H("696.d.6.E",3,"A customer needs a quiz that tracks scores, but the program only asks questions. Comparing these shows:","a gap between functionality and needs",["a perfect match","a faster computer","a new logo"],"Comparison reveals missing features.")
H("696.d.6.E",4,"A fair comparison of a program to customer needs uses:","a list of the customer's stated requirements",["the developer's opinion only","the program's file size","the number of lines"],"Requirements are the yardstick.")
H("696.d.6.F",3,"A flowchart lacks a step to save results, which the customer required. The team should:","add the missing step to the flowchart",["delete the requirement","ignore the customer","remove the flowchart"],"Update designs to include requirements.")
H("696.d.6.F",4,"Adding missing specifications to a flowchart before coding helps by:","planning the change before writing code",["wasting time","deleting data","hiding bugs"],"Planning avoids rework.")
H("696.d.6.G",3,"A developer adds a score-saving feature to a quiz program. This is:","developing new code to meet a specification",["breaking the program","removing a feature","copying a competitor"],"New code adds required features.")
H("696.d.6.G",4,"After writing new code, the developer should explain it by:","using comments and documentation",["deleting the old notes","hiding the code","using single-letter names"],"Explanation aids future readers.")
H("696.d.6.H",3,"The team predicted the app would load in 1 second; it took 5. Comparing these helps to:","find where the product needs redesign",["prove the design is perfect","skip testing","hide the result"],"Gaps between prediction and result guide redesign.")
H("696.d.6.H",4,"A gap between predicted and actual functionality is best treated as:","useful data for generating redesign ideas",["a reason to give up","something to hide","proof of success"],"Differences point to improvements.")
H("696.d.7.A",3,"A black box model shows a system's:","inputs and outputs without its inner workings",["every line of code","wiring colors","team members"],"Black boxes hide internals.")
H("696.d.7.A",4,"A functional model differs from a black box model because it shows:","the internal functions and how they connect",["only the final product","only the cost","no inputs"],"Functional models open the box.")
H("696.d.7.B",3,"In a gallery walk, team members:","view each other's ideas and give feedback",["write final code","buy parts","grade tests"],"Gallery walks share and critique ideas.")
H("696.d.7.B",4,"The main rule of brainstorming's idea-generation stage is to:","produce many ideas without criticizing them yet",["pick one idea immediately","reject silly ideas","work alone in silence"],"Quantity first, judgment later.")
H("696.d.7.C",3,"A Pugh chart compares design concepts by rating them against:","a baseline using the same criteria",["the team's mood","the date","the budget of rivals"],"Pugh charts compare to a baseline.")
H("696.d.7.C",4,"A weighted decision matrix gives more influence to criteria that are:","more important to the project",["listed first","easier to measure only","less costly"],"Weights reflect importance.")
H("696.d.8.A",3,"A student chooses a ruler for measuring and a multimeter for checking voltage. This is:","selecting appropriate tools for the task",["breaking safety rules","skipping design","ignoring specs"],"Match tools to tasks.")
H("696.d.8.A",4,"Using the wrong tool for a task can:","cause errors or injury",["improve accuracy","save all time","protect the device"],"Appropriate tools prevent problems.")
H("696.d.8.B",3,"An engineering notebook is used to:","record design decisions, tests and results",["store music","play games","print posters"],"Notebooks document the process.")
H("696.d.8.B",4,"A good notebook entry includes the date, what was done and:","the results and next steps",["unrelated doodles","the weather only","the cafeteria menu"],"Complete entries support later review.")
H("696.d.8.C",3,"A developer writes a small piece of code, tests it, and fixes errors before adding more. This is:","developing, testing and refining throughout the process",["waiting until the end to test","avoiding all testing","copying code"],"Iterative testing catches errors early.")
H("696.d.8.C",4,"Testing small code sections often is useful because it:","makes bugs easier to locate",["hides bugs","slows all progress forever","removes the need for design"],"Smaller scope narrows the search.")
H("696.d.8.D",3,"A schematic uses symbols to show:","how circuit components are connected",["the programmer's age","the text of the code","the grading scale"],"Schematics are electrical diagrams.")
H("696.d.8.D",4,"When building a circuit from a diagram, a student should check that each connection:","matches the diagram before powering on",["is random","is hidden","is guessed"],"Verify before applying power.")
H("696.d.8.E",3,"A solderless breadboard lets students:","connect components without soldering",["print code","charge phones","store files"],"Breadboards allow quick prototyping.")
H("696.d.8.E",4,"A microcontroller circuit with an LED usually needs a resistor to:","limit the current so the LED isn't damaged",["make it brighter forever","change its color","speed up the code"],"Resistors limit current.")
H("696.d.8.F",3,"Starting a design from an existing baseline design means:","improving something that already exists",["ignoring all prior work","starting with no ideas","avoiding testing"],"Baselines give a starting point.")
H("696.d.8.F",4,"Beginning with a baseline design is useful because it:","gives a reference to compare and improve",["removes the need for testing","guarantees success","eliminates constraints"],"Baselines enable comparison.")
H("696.d.8.G",3,"Running a simulation of a robot arm before building it helps to:","test hardware ideas without risk or cost",["avoid all design","damage real parts","skip planning"],"Simulations mimic real events.")
H("696.d.8.G",4,"A simulation is useful for hardware development because it:","predicts behavior before parts are built",["replaces all testing forever","is always perfect","needs no inputs"],"Models predict outcomes.")
H("696.d.8.H",3,"A limitation of a simulation is that it:","simplifies real-world conditions",["is always exact","has no assumptions","never needs data"],"Models leave out details.")
H("696.d.8.H",4,"When critiquing a model, a team should explain both its usefulness and its:","limitations",["price","logo","speed only"],"Good critiques cover both sides.")
H("696.d.8.I",3,"A team builds a working version, tests it against the requirements and improves it. This is the:","prototype cycle",["marketing plan","shipping process","licensing step"],"Prototypes are built, tested and refined.")
H("696.d.8.I",4,"A prototype fails a requirement during testing. The team should:","refine the prototype and test again",["ignore the failure","delete the requirement quietly","ship it anyway"],"Fix and retest.")
H("696.d.8.J",3,"After prototyping, the team reports the product's final design by describing its:","features, specifications and results",["lunch plans","stray ideas","unused parts"],"Final reports summarize the design.")
H("696.d.8.J",4,"A final design report should explain:","how the design meets requirements",["only the cost of tape","the team's favorite songs","the weather"],"Reports show requirements were met.")
H("696.d.9.A",3,"A robot arm's joint angle can be found from side lengths using:","trigonometry",["a spreadsheet's color","file compression","word processing"],"Trig relates angles and sides.")
H("696.d.9.A",4,"Given two segments of an arm and a target point, the law of cosines helps to:","calculate the joint angle needed",["rename the variables","draw a flowchart","compress an image"],"Geometry gives angles from lengths.")
H("696.d.9.B",3,"A program that repeats a calculation each time a sensor updates uses a:","loop",["comment","header","license"],"Loops repeat calculations.")
H("696.d.9.B",4,"Applying math cyclically in a program means the algorithm:","runs the same calculation repeatedly on new data",["runs once and stops","never uses numbers","only prints text"],"Cyclic algorithms repeat.")
H("696.d.9.C",3,"Checking whether an algorithm gives correct results for many test cases is:","verifying the algorithm",["painting the case","naming variables","buying parts"],"Verification confirms correctness.")
H("696.d.9.C",4,"Between two correct algorithms, the more efficient one:","uses fewer steps or resources",["has more lines","is always longer","costs more"],"Efficiency means fewer resources.")
H("696.d.10.A",3,"Software that reads a button press and turns on a motor is a:","software interface that communicates with hardware",["spreadsheet","word document","paper map"],"It bridges software and hardware.")
H("696.d.10.A",4,"A microcontroller program controls a servo by sending:","a signal to the pin the servo is wired to",["an email","a printed page","a letter"],"Hardware control is through pins.")
H("696.d.10.B",3,"A robot design uses a function to compute speed and needs to know how motors use electricity. This applies ideas from:","computer science and science together",["art only","history only","music only"],"Engineering combines subjects.")
H("696.d.10.B",4,"Understanding mechanics helps a programmer who controls a robot arm because it explains:","how forces and motion affect movement",["how fonts are drawn","how web pages load","how emails are sent"],"Mechanics governs motion.")
H("696.d.10.C",3,"A program converts a raw sensor reading of 0–1023 into a distance in centimeters. This is:","abstraction using intuitive variables",["a hardware repair","a license","a comment"],"Abstraction hides raw numbers.")
H("696.d.10.C",4,"Naming a function getDistanceCm() instead of using raw values everywhere makes code:","easier to read and use",["harder to read","longer to run","unable to be tested"],"Abstraction makes code intuitive.")
H("696.d.11.A",3,"A team combines a motor-control program and a sensor program into one robot program. This is:","integrating small programs into a larger solution",["deleting code","drawing a flowchart","a licensing step"],"Systems thinking joins parts.")
H("696.d.11.A",4,"When integrating small programs, the team should check that the parts:","work correctly together",["are all hidden","are all deleted","have identical names"],"Integration testing confirms cooperation.")
H("696.d.11.B",3,"A variable named speedLimit is better than x because it:","tells readers what the value means",["is shorter","is faster","uses less memory"],"Intuitive names aid readability.")
H("696.d.11.B",4,"Adding comments to a block of code mainly helps:","other people and future you understand it",["the compiler run faster","the computer store less data","the code run backward"],"Comments aid readers.")
H("696.d.11.C",3,"In a program, a picture can be stored as a:","grid (array) of pixel values",["list of fonts","spreadsheet formula","single letter"],"Images are arrays of numbers.")
H("696.d.11.C",4,"Storing the frequency 440 in a variable named noteA is an example of:","abstraction",["compression","encryption","deletion"],"Names stand for numbers.")
H("696.d.11.D",3,"A library function needs a particular data type, but the image is in another. The programmer must:","convert the image data to the required type",["delete the image","rename the function","ignore the error"],"Types must match.")
H("696.d.11.D",4,"An error says an image array has the wrong type for a function. The best fix is to:","convert the array to the type the function expects",["delete the function","unplug the computer","rename the file"],"Convert data to match library requirements.")
H("696.d.11.E",3,"A program that updates an image whenever a user moves a slider uses:","a loop and conditions to respond to input in real time",["a single print statement","no logic","a static image only"],"Loops and ifs react to inputs.")
H("696.d.11.E",4,"A trackbar value changes a brightness threshold. The program shows the new image by:","re-applying the threshold each loop and redrawing",["running once","hiding the image","ignoring the trackbar"],"Repeated updates show changes live.")
H("696.d.11.F",3,"Writing steps in plain English that outline a program's logic before coding is:","pseudocode",["machine code","a compiler","a comment-only file"],"Pseudocode plans logic in words.")
H("696.d.11.F",4,"Together, flowcharts, pseudocode and comments serve to:","document and explain software design",["hide design decisions","slow down coding","replace testing"],"They explain the design.")
H("696.d.11.G",3,"An interface that shows sensor values to a user and also controls a motor communicates with:","both users and hardware",["only paper","only the compiler","nothing"],"Interfaces bridge users and devices.")
H("696.d.11.G",4,"A good interface for a robot controller shows the user the:","current status and available controls",["code's file size","internet history","programmer's name"],"Clear status and controls aid users.")
H("696.d.11.H",3,"Using a library's function without knowing how it works inside is treating it as a:","black box",["glass box","blank page","legal notice"],"Black box use relies on inputs and outputs.")
H("696.d.11.H",4,"Treating imported code as a black box means a programmer only needs to know its:","inputs and what it returns",["internal line count","author's address","commit history"],"Interface, not internals.")
H("696.d.11.I",3,"Representing a robot's joint as four points in a plane is an example of:","abstraction",["encryption","compression","cabling"],"Simple points stand for a complex joint.")
H("696.d.11.I",4,"Four points describing a joint help a program calculate:","the angle between the connected segments",["the file size","the battery type","the code color"],"Points give geometry.")
H("696.d.11.J",3,"A student says \"I wrote a function to repeat these steps.\" This shows correct use of:","programming vocabulary",["wiring symbols","engineering notebooks","safety signs"],"Right terms communicate clearly.")
H("696.d.11.J",4,"Using terms like variable, loop and function accurately helps a team to:","communicate clearly about code",["avoid testing","hide their work","shorten programs"],"Shared vocabulary supports collaboration.")
H("696.d.12.A",3,"Video is processed as a sequence of:","image frames",["single words","audio-only files","spreadsheet cells"],"Videos are frame sequences.")
H("696.d.12.A",4,"Organizing image data into arrays and frames before processing makes it:","possible to apply algorithms in a consistent way",["impossible to analyze","unreadable","unchangeable"],"Structure enables processing.")
H("696.d.12.B",3,"A program analyzes camera data and tells the user a part is misaligned. It used data to:","make decisions and instruct users",["print posters","recolor the case","buy parts"],"Analysis supports decisions.")
H("696.d.12.B",4,"Analyzing complex data to instruct users requires the program to turn raw numbers into:","clear, meaningful information",["random sounds","blank screens","more raw numbers"],"Clear output helps users act.")
H("696.d.12.C",3,"A program reads sensor data, runs an algorithm and sends a motor command. It creates:","output commands from incoming data",["a paper copy","a new password","a licensing file"],"Input to algorithm to output.")
H("696.d.12.C",4,"In a data-driven program, the algorithm's role is to:","transform input data into useful output",["delete the input","store only comments","print only the date"],"Algorithms process data.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_89.jsonl"))
